'use strict';
// Editorial selection and planning use only choices made in this prototype.
function addDays(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function weekStart(date){const d=new Date(date+'T12:00:00');return addDays(date,-((d.getDay()+6)%7));}
function shortDate(date){return new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'});}
function lookRank(x){const p=M.prefs,f=M.contentFeedback?.[x.id];const editorial=['coils','everyday','bare-face','bun'];return (editorial.includes(x.id)?0.5:0)+(p.interests.includes(x.domain)?4:0)+(x.texture?.includes(p.hair)?5:0)+(p.makeup==='Sans maquillage'?(x.id==='bare-face'?10:x.domain==='Maquillage'?-10:0):0)+(p.time==='Moins de 5 min'&&x.minutes<=5?3:0)+(M.saved.includes(x.id)?2:0)+(f==='again'?6:f==='less'?-20:0);}
function lookPractical(x){const entries={waves:['Cheveux ondulés, longueurs souples','Un peigne et vos gestes habituels'],bun:['Cheveux assez longs pour être attachés','Un élastique et quelques épingles'],layers:['Une référence à discuter au salon','5 min pour préparer votre demande'],pixie:['Une référence de coupe courte','5 min pour noter vos envies avant le salon'],coils:['Textures bouclées et crépues','Vos gestes habituels, sans nouvel achat'],sleek:['Cheveux raides, longueur autour des épaules','Un peigne, si vous en avez besoin'],glam:['Fini léger, tons chauds','Vos produits de teint, yeux et lèvres'], 'soft-glam':['Regard cuivré, intensité douce','Vos teintes habituelles et un pinceau'], 'bare-face':['Sans maquillage','Une coiffure et une pièce que vous aimez']};const [fit,tools]=entries[x.id]||[x.pieces?'Avec mes vêtements':x.domain==='Garde-robe'?'Une association à adapter à mes pièces':'Une inspiration à adapter à mes envies',x.domain==='Garde-robe'||x.pieces?'Mes pièces et mes accessoires':'Mes produits et mon matériel habituels'];return `<div class="practical-grid"><div><span>${icon('clock')} Temps</span><strong>${x.minutes||5} min${x.referenceOnly?' de préparation':''}</strong></div><div><span>${icon('heart')} Budget</span><strong>${esc(x.budget||'Avec ce que j’ai')}</strong></div></div>`+P(esc(fit))+moreActions(P(esc(LOOK_GUIDES[x.id]?.tools||tools)),'Ce qu’il me faut');}
function lookFeedbackPanel(id){const x=item(id);if(!x)return '';return panel(`<span class="eyebrow">Un repère pour la prochaine fois</span><h2>Ce look vous a plu ?</h2><p class="subtle">${esc(x.name)}</p><div class="feedback-options">${A('À refaire','look-feedback',{id,value:'again'},'secondary')}${A('À adapter','look-feedback',{id,value:'adapt'},'secondary')}${A('Pas pour moi','look-feedback',{id,value:'less'},'text-button')}</div>${A('Plus tard','feedback-dismiss',{},'text-button')}`);}
function weekCandidates(){return [...CATALOG,...M.outfits].filter(x=>x.type==='Look'&&!x.referenceOnly&&!x.components&&M.contentFeedback?.[x.id]!=='less').sort((a,b)=>lookRank(b)-lookRank(a));}
function weekDraftModal(){const draft=M.weekDraft;if(!draft)return;modal('Trois idées pour ma semaine',P('Changez une idée, choisissez ses jours, puis gardez ce qui vous plaît.')+form('week-plan',draft.slots.map((s,i)=>{const x=item(s.ref);return `<div class="week-draft-row">${imageFor(x.image,'avatar',x.name)}<div><strong>${esc(x.name)}</strong><small>${x.minutes||5} min, ${esc(x.budget||'Avec mes pièces')}</small>${field('date'+i,'Jour de cette idée',s.date,'date',true)}</div>${A(icon('refresh'),'week-replace',{index:i,label:'Remplacer '+x.name},'icon-button')}</div>`;}).join(''),'Garder ces idées')+note('Vos routines déjà prévues restent en place.'));}
function preserveWeekDates(){captureDrafts();const d=M.formDrafts['week-plan']||{};M.weekDraft?.slots.forEach((s,i)=>{if(d['date'+i])s.date=d['date'+i];});}
Object.assign(ACTIONS,{
 'start-intent':d=>{M.started=true;M.startIntent=d.intent;M.navRoot=d.intent==='look'?'DEC-01':'ACC-01';if(d.intent==='event')go('ACC-01');else if(d.intent==='routine')go('ROU-01');else go('ENT-04');},
 'open-day':d=>{M.day=d.date;go('ACC-03');},
 'week-move':d=>{M.weekDate=addDays(weekStart(M.weekDate||DATE()),Number(d.delta));render({scroll:0});},
 'suggest-week':()=>{const xs=weekCandidates();if(!xs.length){toast('Ajoutez une inspiration à vos envies pour commencer.');return;}let start=weekStart(M.weekDate||DATE()),days=Array.from({length:7},(_,i)=>addDays(start,i)).filter(d=>d>=DATE());if(days.length<3){start=addDays(weekStart(DATE()),7);days=Array.from({length:7},(_,i)=>addDays(start,i));}const slots=[0,Math.floor((days.length-1)/2),days.length-1].map((n,i)=>({date:days[n],ref:xs[i%xs.length].id}));M.weekDraft={start,slots};clearDrafts('week-plan');weekDraftModal();},
 'week-replace':d=>{preserveWeekDates();const i=Number(d.index),s=M.weekDraft?.slots[i];if(!s)return;const xs=weekCandidates(),used=M.weekDraft.slots.map(x=>x.ref);const x=xs.find(x=>!used.includes(x.id));if(x)s.ref=x.id;else toast('Vous avez exploré toutes les idées disponibles.');clearDrafts('week-plan');weekDraftModal();},
 'look-feedback':d=>{M.contentFeedback||={};M.contentFeedback[d.id]=d.value;M.feedbackLook=null;if(d.value==='adapt'){M.observationEdit=null;clearDrafts('observation');M.formDrafts['observation:new']={date:DATE(),feeling:'À ajuster',note:'Pour '+item(d.id)?.name+', la prochaine fois : '};go('PRO-03',{context:{observationPhoto:''}});}else{render();toast(d.value==='again'?'Gardé parmi vos idées à refaire.':'Vos prochaines suggestions en tiendront compte.');}},
 'feedback-dismiss':()=>{M.feedbackLook=null;render();},
 'look-less':d=>{M.contentFeedback||={};M.feedbackPrevious={id:d.id,value:M.contentFeedback[d.id]};M.contentFeedback[d.id]='less';toast('Cette idée apparaîtra moins dans vos suggestions.',{label:'Annuler',action:'undo-feedback'});},
 'undo-feedback':()=>{const p=M.feedbackPrevious;if(p){if(p.value)M.contentFeedback[p.id]=p.value;else delete M.contentFeedback[p.id];M.feedbackPrevious=null;}render();toast('Préférence rétablie.');},
 'reset-feedback':()=>{M.contentFeedback={};render();toast('Toutes les inspirations peuvent à nouveau être proposées.');},
 'salon-ready':()=>{const x=currentLook();if(!x)return;if(!M.saved.includes(x.id))M.saved.push(x.id);go('SAV-01');toast('Référence gardée pour votre prochain rendez-vous.');}
});
F['week-plan']=d=>{const w=M.weekDraft;if(!w)return formError('Préparez d’abord votre sélection.');if(w.slots.some((s,i)=>!/^\d{4}-\d{2}-\d{2}$/.test(d['date'+i]||'')||d['date'+i]<DATE()))return formError('Choisissez des jours à partir d’aujourd’hui.');w.slots.forEach((s,i)=>addPlan(item(s.ref),d['date'+i]));M.weekDate=w.start;M.weekDraft=null;closeModal();go('ACC-02');toast('Vos idées sont prêtes pour la semaine.');};

ACTIONS['session-detail']=d=>{const s=M.sessions.find(s=>s.id===d.id);if(!s)return;modal(esc(s.name||'Ma séance'),P(dateText(s.date))+(s.kind==='routine'?tag(sessionComplete(s)?'Réalisée':'Séance partielle')+`<ol class="all-steps">${(s.labels||[]).map((t,i)=>`<li><strong>${esc(routineSessionStepLabel(s,i))}</strong>, ${s.steps[i]==='done'?'Fait':s.steps[i]==='skip'?'Passé':'À faire'}${s.skinEntries?.[i]?.product?.name?`<p>${esc(t)}</p>`:''}</li>`).join('')}</ol>`:P('Look réalisé et confirmé par vous.'))+P(esc(s.note||''))+(s.kind==='routine'&&M.routines.some(r=>r.id===s.ref)?A('Revoir cette séance','session-resume',{id:s.id},'secondary'):''));};
ACTIONS['session-resume']=d=>{const s=M.sessions.find(s=>s.id===d.id);if(s)go('ROU-04',{context:{routine:s.ref,sessionDate:s.date}});};
function sessionJournal(){const list=M.sessions.filter(s=>s.confirmed||s.kind==='tutorial'||s.steps?.some(v=>v!=='todo')).slice().sort((a,b)=>b.date.localeCompare(a.date));return list.length?list.map(s=>A(`<span><strong>${esc(s.name||'Ma routine')}</strong><small>${dateText(s.date)}, ${s.kind==='routine'?(sessionComplete(s)?'Réalisée':'Partielle'):'Look réalisé'}</small></span>${icon('chev')}`,'session-detail',{id:s.id},'glass list-row journal-entry')).join(''):empty('Vos prochains moments seront ici','Vos séances et looks réalisés apparaîtront après confirmation.');}
